/**
 * VeriWrite - Writing Indicator Builder
 *
 * Evaluates stylometric measurements against approved experimental heuristics
 * and constructs writingIndicatorSchema-compliant indicator objects.
 *
 * Supported Indicators in MVP:
 * - UNIFORM_SENTENCE_CADENCE
 * - LOW_LEXICAL_DIVERSITY
 * - ELEVATED_TRANSITION_DENSITY
 * - REPETITIVE_SYNTACTIC_STARTERS
 * - FORMULAIC_PHRASE_USAGE
 *
 * NOTE: HIGH_PREDICTABILITY_PASSAGES and PERPLEXITY_ANOMALY are reserved
 * for future statistical/neural inference runtimes and are NOT generated by heuristics.
 */

import { buildEvidenceItem } from "./evidenceBuilder.js";

/**
 * Builds writing indicators based on stylometric measurements.
 *
 * @param {object} analysisData - Data containing extractedText, sentences, metrics, etc.
 * @param {object} options - Options including isAdvisoryOnly (for 100–149 word texts).
 * @returns {Array<object>} Array of schema-compliant indicator objects.
 */
export function buildIndicators(analysisData, options = {}) {
  const { isAdvisoryOnly = false } = options;
  const {
    extractedText,
    sentences,
    wordCount,
    sentenceMetrics,
    mattr,
    transitionData,
    starterPatterns,
    formulaicMatches,
  } = analysisData;

  const indicators = [];

  // Helper to adjust label and severity for 100–149 word advisory-only tier
  const formatIndicator = (ind) => {
    if (isAdvisoryOnly) {
      return {
        ...ind,
        label: `Advisory: ${ind.label}`,
        severity: "Low",
        explanation: `${ind.explanation} (Advisory notice: This passage contains 100–149 words; statistical patterns are preliminary).`,
      };
    }
    return ind;
  };

  // 1. UNIFORM_SENTENCE_CADENCE
  // Evaluated when sentences >= 8
  if (sentences.length >= 8 && wordCount >= 100) {
    const cv = sentenceMetrics.cv;
    let severity = null;

    if (cv < 0.28) {
      severity = "High";
    } else if (cv < 0.38) {
      severity = "Medium";
    }

    if (severity) {
      // Find up to 3 sentences with lengths closest to the mean
      const sortedByCloseness = [...sentences]
        .filter((s) => s.wordCount > 5)
        .sort(
          (a, b) =>
            Math.abs(a.wordCount - sentenceMetrics.mean) -
            Math.abs(b.wordCount - sentenceMetrics.mean)
        )
        .slice(0, 3);

      const evidence = sortedByCloseness.map((s) =>
        buildEvidenceItem(extractedText, {
          charStart: s.charStart,
          charEnd: s.charEnd,
          paragraphIndex: s.paragraphIndex,
          sentenceIndex: s.sentenceIndex,
          flagReason: `Sentence length (${s.wordCount} words) closely matches document average (${sentenceMetrics.mean} words, CV: ${cv}).`,
        })
      );

      indicators.push(
        formatIndicator({
          code: "UNIFORM_SENTENCE_CADENCE",
          label: "Uniform Sentence Cadence",
          severity,
          explanation: `Sentence lengths exhibit low variance (Coefficient of Variation: ${cv}, mean: ${sentenceMetrics.mean} words). In academic writing, low variance may reflect structured expository formatting or formulaic pacing.`,
          evidence,
        })
      );
    }
  }

  // 2. LOW_LEXICAL_DIVERSITY
  // Evaluated when MATTR is available (tokens >= 50)
  if (typeof mattr === "number" && wordCount >= 100) {
    let severity = null;
    if (mattr < 0.62) {
      severity = "High";
    } else if (mattr < 0.7) {
      severity = "Medium";
    }

    if (severity) {
      // Document-level evidence describing the MATTR score
      const docEvidence = buildEvidenceItem(extractedText, {
        charStart: null,
        charEnd: null,
        paragraphIndex: 0,
        snippet: `Moving-Average Type-Token Ratio across 50-word windows is ${mattr}.`,
        flagReason: `Restricted vocabulary breadth across consecutive 50-word windows (MATTR: ${mattr}).`,
      });

      indicators.push(
        formatIndicator({
          code: "LOW_LEXICAL_DIVERSITY",
          label: "Low Lexical Diversity",
          severity,
          explanation: `Vocabulary richness measured via Moving-Average Type-Token Ratio is ${mattr} (threshold < 0.70). This indicates constrained vocabulary variety across consecutive text windows.`,
          evidence: [docEvidence],
        })
      );
    }
  }

  // 3. ELEVATED_TRANSITION_DENSITY
  // Evaluated when sentences >= 5
  if (sentences.length >= 5 && transitionData && transitionData.score > 0.45) {
    const density = transitionData.score;
    const severity = density > 0.65 ? "High" : "Medium";

    // Take up to 4 representative sentences containing transitions
    const sampleSentences = transitionData.matchingSentences.slice(0, 4);
    const evidence = sampleSentences.map((item) =>
      buildEvidenceItem(extractedText, {
        charStart: item.sentence.charStart,
        charEnd: item.sentence.charEnd,
        paragraphIndex: item.sentence.paragraphIndex,
        sentenceIndex: item.sentence.sentenceIndex,
        flagReason: `Contains formal discourse marker(s): ${item.matchedPhrases.join(", ")}.`,
      })
    );

    indicators.push(
      formatIndicator({
        code: "ELEVATED_TRANSITION_DENSITY",
        label: "Elevated Transition Density",
        severity,
        explanation: `${Math.round(density * 100)}% of sentences begin with or incorporate formal transition connectives. High transition density is common in structured essays and formulaic templates.`,
        evidence,
      })
    );
  }

  // 4. REPETITIVE_SYNTACTIC_STARTERS
  // Evaluated when repetitive starter patterns are detected
  if (Array.isArray(starterPatterns) && starterPatterns.length > 0) {
    for (const pattern of starterPatterns) {
      const severity =
        pattern.type === "CONTIGUOUS_RUN" && pattern.sentences.length >= 4
          ? "High"
          : "Medium";

      const sampleSentences = pattern.sentences.slice(0, 3);
      const evidence = sampleSentences.map((s) =>
        buildEvidenceItem(extractedText, {
          charStart: s.charStart,
          charEnd: s.charEnd,
          paragraphIndex: s.paragraphIndex,
          sentenceIndex: s.sentenceIndex,
          flagReason: `Sentence opening matches pattern "${pattern.bigram}".`,
        })
      );

      const explanationDesc =
        pattern.type === "CONTIGUOUS_RUN"
          ? `${pattern.sentences.length} consecutive sentences begin with the identical two-word opening "${pattern.bigram}".`
          : `${Math.round((pattern.frequencyRatio || 0) * 100)}% of sentences in the document begin with "${pattern.bigram}".`;

      indicators.push(
        formatIndicator({
          code: "REPETITIVE_SYNTACTIC_STARTERS",
          label: "Repetitive Sentence Starters",
          severity,
          explanation: `${explanationDesc} Repeated sentence starters may reflect parallel rhetorical structure or template-driven drafting.`,
          evidence,
        })
      );
    }
  }

  // 5. FORMULAIC_PHRASE_USAGE
  // Evaluated when >= 2 distinct formulaic phrases match
  if (Array.isArray(formulaicMatches) && formulaicMatches.length >= 2) {
    const matchCount = formulaicMatches.length;
    const severity = matchCount >= 4 ? "High" : "Medium";

    // Map each formulaic match to its containing sentence
    const sampleMatches = formulaicMatches.slice(0, 3);
    const evidence = sampleMatches.map((m) => {
      // Find sentence enclosing this match
      const enclosingSentence = sentences.find(
        (s) => s.charStart <= m.charStart && s.charEnd >= m.charEnd
      );

      const start = enclosingSentence ? enclosingSentence.charStart : m.charStart;
      const end = enclosingSentence ? enclosingSentence.charEnd : m.charEnd;
      const pIdx = enclosingSentence ? enclosingSentence.paragraphIndex : 0;
      const sIdx = enclosingSentence ? enclosingSentence.sentenceIndex : null;

      return buildEvidenceItem(extractedText, {
        charStart: start,
        charEnd: end,
        paragraphIndex: pIdx,
        sentenceIndex: sIdx,
        flagReason: `Contains formulaic stock expression: "${m.phrase}".`,
      });
    });

    indicators.push(
      formatIndicator({
        code: "FORMULAIC_PHRASE_USAGE",
        label: "Formulaic Phrase Usage",
        severity,
        explanation: `${matchCount} instances of common stock academic clichés or template idioms were identified. Formulaic phrases reflect stylistic idiom density and do not establish AI authorship.`,
        evidence,
      })
    );
  }

  return indicators;
}
